'use strict';
const http = require('http');
const fs = require('fs');
const path = require('path');

const PORT = Number(process.env.PORT || 8080);
const API = process.env.API_URL || 'http://api:8000';
const API_PREFIX = process.env.API_PREFIX === undefined ? '/api' : process.env.API_PREFIX;

function proxy(req, res) {
  const target = new URL(req.url, API); // keeps path + query verbatim
  const headers = Object.assign({}, req.headers, { host: target.host });
  delete headers['content-length'];
  const up = http.request({
    hostname: target.hostname, port: target.port, path: target.pathname + target.search,
    method: req.method, headers, timeout: 15000,
  }, (r) => {
    const outHeaders = Object.assign({}, r.headers);
    res.writeHead(r.statusCode || 502, outHeaders);
    r.pipe(res);
  });
  up.on('timeout', () => up.destroy(new Error('upstream timeout')));
  up.on('error', (e) => {
    if (!res.headersSent) {
      res.writeHead(502, { 'content-type': 'application/json' });
      res.end(JSON.stringify({ error: 'api unreachable: ' + e.message }));
    } else { res.end(); }
  });
  req.pipe(up);
}

const STATIC = {
  '/': 'index.html',
  '/index.html': 'index.html',
  '/app.js': 'app.js',
  '/style.css': 'style.css',
};

const server = http.createServer((req, res) => {
  let p;
  try { p = new URL(req.url, 'http://localhost').pathname; } catch (e) { p = '/' }
  if (p === '/healthz') {
    res.writeHead(200, { 'content-type': 'application/json' });
    return res.end(JSON.stringify({ ok: true }));
  }
  if (API_PREFIX && (p === API_PREFIX || p.startsWith(API_PREFIX + '/'))) {
    return proxy(req, res);
  }
  if (API_PREFIX === '' && (p.startsWith('/items') || p === '/health')) {
    return proxy(req, res);
  }
  const name = STATIC[p];
  if (name) {
    fs.readFile(path.join(__dirname, 'public', name), (err, data) => {
      if (err) { res.writeHead(500); return res.end('error'); }
      const type = name.endsWith('.html') ? 'text/html; charset=utf-8'
        : name.endsWith('.js') ? 'application/javascript; charset=utf-8'
        : 'text/css; charset=utf-8';
      res.writeHead(200, { 'content-type': type, 'cache-control': 'no-cache' });
      res.end(data);
    });
    return;
  }
  res.writeHead(404, { 'content-type': 'text/plain' });
  res.end('not found');
});
server.listen(PORT, '0.0.0.0', () => console.log('ui listening on ' + PORT + ', api at ' + API));
EOF
