{"command": "cd ~/repo-b/ui/public && cat > app.js <<'EOF'
(function () {
  'use strict';
  var API = '/api';
  var POLL_MS = 1000;
  var form = document.getElementById('add-form');
  var input = document.getElementById('item');
  var list = document.getElementById('list');
  var empty = document.getElementById('empty');
  var statusEl = document.getElementById('status');

  var items = [];           // last server snapshot
  var pending = {};         // id -> desired bought (optimistic, not yet confirmed)
  var polling = false;
  var refreshing = false;
  var lastError = null;

  function setStatus(msg, isError) {
    statusEl.textContent = msg || '';
    statusEl.className = 'status' + (isError ? ' error' : '');
    lastError = isError ? msg : null;
  }

  function key(it) { return it.id !== undefined && it.id !== null ? String(it.id) : ''; }

  function itemEl(it) {
    var k = key(it);
    var li = document.createElement('li');
    li.dataset.id = k;
    var cb = document.createElement('input');
    cb.type = 'checkbox';
    cb.id = 'item-' + k;
    cb.checked = !!it.bought;
    cb.addEventListener('change', function () { toggle(it, cb.checked, cb); });
    var label = document.createElement('label');
    label.htmlFor = cb.id;
    label.textContent = it.name;
    li.appendChild(cb);
    li.appendChild(label);
    if (cb.checked) li.classList.add('bought');
    return li;
  }

  function render() {
    list.textContent = '';
    var seen = {};
    items.forEach(function (it) {
      var k = key(it);
      seen[k] = true;
      list.appendChild(itemEl(it));
    });
    // keep locally-added items the server has not reported yet visible? no: snapshot is truth
    empty.style.display = items.length ? 'none' : '';
  }

  function withPending(snapshot) {
    return snapshot.map(function (it) {
      var k = key(it);
      if (Object.prototype.hasOwnProperty.call(pending, k) && pending[k].name === it.name) {
        var copy = {};
        for (var p in it) copy[p] = it[p];
        copy.bought = pending[k].bought;
        return copy;
      }
      return it;
    });
  }

  function refresh() {
    if (refreshing) return;
    refreshing = true;
    fetch(API + '/items', { headers: { accept: 'application/json' }, cache: 'no-store' })
      .then(function (r) {
        if (!r.ok) throw new Error('HTTP ' + r.status);
        return r.json();
      })
      .then(function (data) {
        var next = Array.isArray(data) ? data : (data && data.items) || [];
        // drop pending entries the server has confirmed
        next.forEach(function (it) {
          var k = key(it);
          if (pending[k] && pending[k].bought === !!it.bought) delete pending[k];
        });
        items = withPending(next);
        render();
        if (lastError) setStatus('connected', false);
        else if (!statusEl.textContent) setStatus('connected', false);
      })
      .catch(function (e) {
        setStatus('cannot reach the server (' + e.message + '), retrying…', true);
      })
      .then(function () { refreshing = false; });
  }

  function toggle(it, bought, cb) {
    var k = key(it);
    pending[k] = { bought: bought, name: it.name };
    it.bought = bought;
    cb.parentNode.classList.toggle('bought', bought);
    setStatus('saving…', false);
    fetch(API + '/items/' + encodeURIComponent(k), {
      method: 'PATCH',
      headers: { 'content-type': 'application/json', accept: 'application/json' },
      body: JSON.stringify({ bought: bought })
    }).then(function (r) {
      if (!r.ok) throw new Error('HTTP ' + r.status);
      delete pending[k];
      setStatus('', false);
      refresh();
    }).catch(function (e) {
      delete pending[k];
      setStatus('could not save the change (' + e.message + '), retrying…', true);
      refresh();
    });
  }

  form.addEventListener('submit', function (ev) {
    ev.preventDefault();
    var name = (input.value || '').trim();
    if (!name) return;
    input.value = '';
    setStatus('adding…', false);
    fetch(API + '/items', {
      method: 'POST',
      headers: { 'content-type': 'application/json', accept: 'application/json' },
      body: JSON.stringify({ name: name })
    }).then(function (r) {
      if (!r.ok) throw new Error('HTTP ' + r.status);
      return r.json().catch(function () { return null; });
    }).then(function () {
      setStatus('', false);
      refresh();
    }).catch(function (e) {
      setStatus('could not add "' + name + '" (' + e.message + ')', true);
      if (!input.value) input.value = name;
    });
  });

  refresh();
  setInterval(refresh, POLL_MS);
  document.addEventListener('visibilitychange', function () { if (!document.hidden) refresh(); });
  window.addEventListener('focus', refresh);
})();
EOF
