(function () {
  'use strict';
  // Talks only to /api/*, which the UI server proxies to the `api` service.
  // Contract (agreed with repo-a): GET /items -> {version, items:[{id,text,bought,updated_at}]},
  // POST /items {text}, PUT /items/{id} {text?,bought?}, DELETE /items/{id}.
  var API = '/api';
  var POLL_MS = 1000;

  var form = document.getElementById('add-form');
  var input = document.getElementById('item');
  var list = document.getElementById('list');
  var empty = document.getElementById('empty');
  var statusEl = document.getElementById('status');

  var items = [];              // last snapshot from the server
  var version = null;          // last seen basket version
  var pendingToggles = {};     // id -> {bought, text}: optimistic, unconfirmed
  var inFlight = false;
  var refreshing = false;
  var statusTimer = null;

  function setStatus(msg, isError, sticky) {
    statusEl.textContent = msg || '';
    statusEl.className = 'status' + (isError ? ' error' : '');
    if (statusTimer) { clearTimeout(statusTimer); statusTimer = null; }
    if (msg && !isError && !sticky) {
      statusTimer = setTimeout(function () { if (statusEl.textContent === msg) setStatus('', false); }, 1500);
    }
  }

  function req(method, url, body) {
    var opts = { method: method, cache: 'no-store', headers: { accept: 'application/json' } };
    if (body !== undefined) {
      opts.headers['content-type'] = 'application/json';
      opts.body = JSON.stringify(body);
    }
    return fetch(url, opts).then(function (r) {
      if (!r.ok) {
        return r.text().then(function (t) {
          var m = t;
          try { m = JSON.parse(t).error || t; } catch (e) { /* raw text */ }
          throw new Error('HTTP ' + r.status + (m ? ': ' + m : ''));
        });
      }
      return r.status === 204 ? null : r.json().catch(function () { return null; });
    });
  }

  function applyPending(snapshot) {
    return snapshot.map(function (it) {
      var p = pendingToggles[String(it.id)];
      if (p) {
        var copy = {};
        for (var k in it) copy[k] = it[k];
        copy.bought = p.bought;
        return copy;
      }
      return it;
    });
  }

  function renderItem(it) {
    var id = String(it.id);
    var li = document.createElement('li');
    li.dataset.id = id;
    if (it.bought) li.className = 'bought';
    var cb = document.createElement('input');
    cb.type = 'checkbox';
    cb.className = 'bought-box';
    cb.id = 'item-' + id;
    cb.checked = !!it.bought;
    cb.setAttribute('aria-label', 'Bought: ' + it.text);
    cb.addEventListener('change', function () { toggle(it, cb.checked); });
    var label = document.createElement('label');
    label.htmlFor = cb.id;
    label.textContent = it.text;
    li.appendChild(cb);
    li.appendChild(label);
    return li;
  }

  function render() {
    list.textContent = '';
    items.forEach(function (it) { list.appendChild(renderItem(it)); });
    empty.style.display = items.length ? 'none' : '';
  }

  function refresh(force) {
    if (refreshing) return;
    refreshing = true;
    req('GET', API + '/items').then(function (data) {
      var next = (data && Array.isArray(data.items)) ? data.items : [];
      var v = data && data.version !== undefined ? data.version : null;
      // A response older than one we already applied is ignored (out-of-order polls).
      if (force || version === null || v === null || v >= version) {
        version = v;
        var nextById = {};
        next.forEach(function (it) { nextById[String(it.id)] = it; });
        Object.keys(pendingToggles).forEach(function (id) {
          var p = pendingToggles[id];
          if (!nextById[id] || nextById[id].bought === p.bought || nextById[id].text !== p.text) delete pendingToggles[id];
        });
        items = applyPending(next);
        render();
      }
      if (statusEl.classList.contains('error')) setStatus('connected', false);
    }).catch(function (e) {
      setStatus('cannot reach the server (' + e.message + '), retrying…', true, true);
    }).then(function () { refreshing = false; });
  }

  function toggle(it, bought) {
    var id = String(it.id);
    pendingToggles[id] = { bought: bought, text: it.text };
    it.bought = bought;
    var li = list.querySelector('li[data-id="' + (window.CSS && CSS.escape ? CSS.escape(id) : id) + '"]');
    if (li) li.classList.toggle('bought', bought);
    inFlight = true;
    req('PUT', API + '/items/' + encodeURIComponent(id), { bought: bought }).then(function (updated) {
      delete pendingToggles[id];
      if (updated && Array.isArray(updated.items)) {
        items = updated.items; version = updated.version === undefined ? version : updated.version; render();
      }
      refresh(true);
    }).catch(function (e) {
      delete pendingToggles[id];
      setStatus('could not save the change (' + e.message + ')', true);
      refresh(true);
    }).then(function () { inFlight = false; });
  }

  form.addEventListener('submit', function (ev) {
    ev.preventDefault();
    var text = (input.value || '').trim();
    if (!text) return;
    input.value = '';
    setStatus('adding…', false, true);
    inFlight = true;
    req('POST', API + '/items', { text: text }).then(function () {
      refresh(true);
      setStatus('', false);
    }).catch(function (e) {
      setStatus('could not add "' + text + '" (' + e.message + ')', true);
      if (!input.value) input.value = text;
    }).then(function () { inFlight = false; });
  });

  function tick() { if (!inFlight) refresh(false); }

  refresh(true);
  setInterval(tick, POLL_MS);
  document.addEventListener('visibilitychange', function () { if (!document.hidden) refresh(true); });
  window.addEventListener('focus', function () { refresh(true); });
})();
EOF
